247	    /** Fixed city-to-region table used to derive an owner's region for its customer code. */
248	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
249	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
250	
251	    /** Region to inclusive 4-digit postcode range {low, high}, preferred over the city table
252	     *  when deriving an owner's region. */
253	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
254	        "NSW", new int[] {2000, 2099},
255	        "VIC", new int[] {3000, 3099},
256	        "QLD", new int[] {4000, 4099});
257	
258	    /**
259	     * Builds an owner's customer code formatted {@code '<REGION>-<HASH8>'}, where REGION is the
260	     * region code derived from the owner's postcode (see {@link #deriveRegion(Owner)}) and HASH8 is
261	     * the first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized
262	     * telephone concatenated with its last name (e.g. {@code 'NSW-1A2B3C4D'}). The old per-city
263	     * sequence numbers have been dropped: the identity is now purely region-and-hash.
264	     */
265	    private String generateCustomerCode(Owner owner) {
266	        return String.format("%s-%s", deriveRegion(owner), hash8(owner));
267	    }
268	
269	    /**
270	     * Derives an owner's region code, preferring the postcode: the region whose inclusive 4-digit
271	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the postcode is used first. When
272	     * the postcode is absent or in no known range, it falls back to the fixed city-to-region table
273	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the
274	     * city is not in the table.
275	     */
276	    private static String deriveRegion(Owner owner) {
277	        String postcode = owner.getPostcode();
278	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
279	            int value = Integer.parseInt(postcode);
280	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
281	                int[] range = entry.getValue();
282	                if (value >= range[0] && value <= range[1]) {
283	                    return entry.getKey();
284	                }
285	            }
286	        }
287	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
288	    }
289	
290	    /**
291	     * Computes an owner's identity hash as the first 8 upper-case hex characters of the SHA-256
292	     * digest over its normalized telephone concatenated with its last name.
293	     */
294	    private static String hash8(Owner owner) {
295	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
296	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
297	        String seed = telephone + lastName;
298	        try {
299	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
300	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
301	            StringBuilder sb = new StringBuilder(hash.length * 2);
302	            for (byte b : hash) {
303	                sb.append(String.format("%02X", b));
304	            }
305	            return sb.substring(0, 8);
306	        }
307	        catch (NoSuchAlgorithmException e) {
308	            throw new IllegalStateException("SHA-256 not available", e);
309	        }
310	    }
