379	    /**
380	     * Returns the existing owners that belong to the household identified by the given last name
381	     * and address, comparing both fields in their normalized form. An empty list is returned when
382	     * either field is absent (no household can be formed).
383	     */
384	    private List<Owner> findHouseholdMembers(String lastName, String address) {
385	        String normalizedLastName = normalizeHouseholdField(lastName);
386	        String normalizedAddress = normalizeHouseholdAddress(address);
387	        if (normalizedLastName == null || normalizedAddress == null) {
388	            return List.of();
389	        }
390	        return ownerRepository.findAll().stream()
391	            .filter(existing -> normalizedLastName.equals(normalizeHouseholdField(existing.getLastName()))
392	                && normalizedAddress.equals(normalizeHouseholdAddress(existing.getAddress())))
393	            .toList();
394	    }
395	
396	    /**
397	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
398	     * runs of whitespace to a single space and lower-casing, so values that differ only in
399	     * whitespace or letter case are treated as equal.
400	     */
401	    private static String normalizeHouseholdField(String value) {
402	        if (value == null) {
403	            return null;
404	        }
405	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
406	    }
407	
408	    /**
409	     * Normalizes an address for household comparison and identity using the same canonical form
410	     * applied when an owner is created (trim/collapse whitespace, upper-case, expand common
411	     * abbreviations), so comparisons always use the normalized address regardless of the form in
412	     * which either value was originally supplied. Returns {@code null} when the address is absent
413	     * or blank, since no household can be formed without one.
414	     */
415	    private static String normalizeHouseholdAddress(String address) {
416	        String normalized = AddressNormalizer.normalize(address);
417	        if (normalized == null || normalized.isBlank()) {
418	            return null;
419	        }
420	        return normalized;
421	    }
422	
423	    /**
424	     * Places {@code owner} into the household formed by owners that share its (normalized) last
425	     * name and address, and returns the household's stable shared identifier. If any existing
426	     * member already carries a household id it is reused; otherwise a stable id is derived from
427	     * the shared last name and address. Every member missing an id (including the given owner)
428	     * is assigned the shared value so all owners in the household agree on it.
429	     */
430	    @Override
431	    @Transactional
432	    public String assignHousehold(Owner owner) throws DataAccessException {
433	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
434	        if (members.isEmpty()) {
435	            return null;
436	        }
437	        String householdId = members.stream()
438	            .map(Owner::getHouseholdId)
439	            .filter(id -> id != null && !id.isBlank())
440	            .findFirst()
441	            .orElseGet(() -> generateHouseholdId(owner.getLastName(), owner.getAddress()));
442	        for (Owner member : members) {
443	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
444	                member.setHouseholdId(householdId);
445	                ownerRepository.save(member);
446	            }
447	        }
448	        owner.setHouseholdId(householdId);
449	        return householdId;
450	    }
451	
452	    /**
453	     * Derives a stable household identifier from the normalized last name and address as the
454	     * first 16 upper-case hex characters of their SHA-256 digest, so the same household always
455	     * maps to the same value regardless of creation order.
456	     */
457	    private static String generateHouseholdId(String lastName, String address) {
458	        String seed = normalizeHouseholdField(lastName) + "\n" + normalizeHouseholdAddress(address);
459	        try {
460	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
461	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
462	            StringBuilder sb = new StringBuilder(hash.length * 2);
463	            for (byte b : hash) {
464	                sb.append(String.format("%02X", b));
465	            }
466	            return sb.substring(0, 16);
467	        }
468	        catch (NoSuchAlgorithmException e) {
469	            throw new IllegalStateException("SHA-256 not available", e);
470	        }
471	    }
